function filter$messageInput(p){
  this.constructor(p);
}
filter$messageInput.prototype = new DirEvent();
filter$messageInput.prototype.beforeInit = function(){
  var p = this._dir;
  p.field('data').allowBlank = p.options.allowBlank;
}
filter$messageInput.prototype.afterInit = function(){
  var p = this._dir;
  p.valLabel('data', p.options.label)
  p.setTitle(p.options.title)
}
filter$messageInput.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir;
  if (p.options.msgFunction) p.options.msgFunction(p, true, p.valForm('data'));
  return false;
}
